        return [(r, c) for r, c in cells if grid[r][c] == 9]

    counts = [len(markers(cells)) for cells in objects]
    min_count = min(counts)
    candidates = [cells for cells, count in zip(objects, counts) if count == min_count]
    target = candidates[0]

    # When the two-marker minimum is a widely separated pair, use the next
    # marker-count tier and prefer its most spatially distributed marker pattern.
    if min_count == 2:
